def pendientes_a_telegram(apps, schema_editor):
    Notification = apps.get_model("notificaciones", "Notification")
    Case = apps.get_model("revision", "Case")
    casos = set()
    for n in Notification.objects.filter(channel="WHATSAPP", status="PENDIENTE_ENVIO").select_related("recipient"):
        chat = n.recipient.telegram_chat_id
        if chat:
            n.channel, n.recipient_chat = "TELEGRAM", chat
        else:
            n.status, n.error = "NO_APLICA", "Anulado: los avisos ahora son solo por Telegram y el destinatario no tiene chat."
        n.save(update_fields=["channel", "recipient_chat", "status", "error"])
        casos.add(n.case_id)
    for case_id in casos:  # mismo resumen que notificaciones.services.case_notification_summary
        estados = set(Notification.objects.filter(case_id=case_id).exclude(status="NO_APLICA")
                      .values_list("status", flat=True))
        resumen = ("NO_APLICA" if not estados else "PENDIENTE_ENVIO" if "PENDIENTE_ENVIO" in estados
                   else "ERROR_ENVIO" if "ERROR_ENVIO" in estados else "ENVIADO")
        Case.objects.filter(pk=case_id).update(notification_status=resumen)


